import type { EditorialBlock, EditorialPage, EditorialSource } from "./editorial-pages";

type WorkbenchItem = Extract<EditorialBlock, { type: "workbench" }>["items"][number];
type PageSpec = Omit<EditorialPage, "blocks" | "publishedAt" | "updatedAt"> & {
  workbenchEyebrow: string;
  workbenchHeading: string;
  workbenchIntro: string;
  workbenchItems: WorkbenchItem[];
  principleHeading: string;
  principleParagraphs: string[];
  principleBullets: string[];
  scenario: Extract<EditorialBlock, { type: "scenario" }>;
  faqItems: Extract<EditorialBlock, { type: "faq" }>["items"];
};

const source = (label: string, href: string, note: string): EditorialSource => ({ label, href, note });
const methodology = source("VibeFootprint methodology", "/methodology", "Defines the public-surface evidence boundary and keeps pattern similarity separate from security and private implementation claims.");
const owaspAsvs = source("OWASP Application Security Verification Standard", "https://owasp.org/www-project-application-security-verification-standard/", "A requirements-based reference for defining and verifying application security controls.");
const owaspAuth = source("OWASP Authentication Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html", "Primary application-security guidance for identity verification, account flows and authentication responses.");
const owaspAuthorization = source("OWASP Authorization Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html", "Primary guidance for deny-by-default, least privilege and server-side permission checks on every request.");
const owaspRest = source("OWASP REST Security Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html", "Primary guidance for protecting REST endpoints, validating requests and enforcing API authorization.");
const owaspSecrets = source("OWASP Secrets Management Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html", "Primary guidance for secret storage, access, rotation, auditing and CI/CD handling.");
const owaspDependencies = source("OWASP Vulnerable Dependency Management", "https://cheatsheetseries.owasp.org/cheatsheets/Vulnerable_Dependency_Management_Cheat_Sheet.html", "A risk-based approach to identifying, analyzing and remediating vulnerable direct and transitive dependencies.");
const owaspInput = source("OWASP Input Validation Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/Input_Validation_Cheat_Sheet.html", "Primary guidance for syntactic and semantic server-side input validation without relying on fragile denylists.");
const owaspErrors = source("OWASP Error Handling Cheat Sheet", "https://cheatsheetseries.owasp.org/cheatsheets/Error_Handling_Cheat_Sheet.html", "Primary guidance for useful application failures that do not expose sensitive implementation detail.");
const nistSsdf = source("NIST Secure Software Development Framework", "https://csrc.nist.gov/projects/ssdf", "A risk-based framework for preparing, protecting, producing and responding throughout software development.");
const nistRecovery = source("NIST contingency planning guide", "https://csrc.nist.gov/pubs/sp/800/34/r1/upd1/final", "Primary planning guidance for recovery strategy, procedures, testing and restoration capability.");
const nistIncident = source("NIST SP 800-61 Rev. 3", "https://csrc.nist.gov/pubs/sp/800/61/r3/final", "Current NIST recommendations for integrating incident response into cybersecurity risk management.");
const postgresData = source("PostgreSQL data-definition documentation", "https://www.postgresql.org/docs/current/ddl.html", "Primary database documentation for constraints, keys, row security, schemas and dependency tracking.");
const webVitals = source("web.dev Core Web Vitals", "https://web.dev/articles/vitals", "Primary browser-performance guidance for measuring loading, responsiveness and visual stability around user experience.");
const wcag = source("W3C Web Content Accessibility Guidelines 2.2", "https://www.w3.org/TR/WCAG22/", "The W3C Recommendation defining testable accessibility requirements, including input, errors, reflow and target size.");
const googleSre = source("Google SRE: Monitoring Distributed Systems", "https://sre.google/sre-book/monitoring-distributed-systems/", "Primary reliability guidance for actionable signals around latency, traffic, errors and saturation.");
const openTelemetry = source("OpenTelemetry signals", "https://opentelemetry.io/docs/concepts/signals/", "Primary documentation for connecting traces, metrics and logs with shared context.");
const pci = source("PCI Security Standards Council", "https://www.pcisecuritystandards.org/standards/", "Official standards information for environments that store, process or transmit payment account data.");
const googleEmail = source("Gmail email sender guidelines", "https://support.google.com/mail/answer/81126?hl=en", "Current first-party sender requirements and guidance for authentication, alignment, delivery and unsubscribe behavior.");

function w(title: string, subtitle: string, fields: WorkbenchItem["fields"], decision: string): WorkbenchItem {
  return { title, subtitle, fields, decision };
}

function page(spec: PageSpec): EditorialPage {
  const {
    workbenchEyebrow,
    workbenchHeading,
    workbenchIntro,
    workbenchItems,
    principleHeading,
    principleParagraphs,
    principleBullets,
    scenario,
    faqItems,
    ...editorial
  } = spec;

  return {
    ...editorial,
    publishedAt: "2026-08-23",
    updatedAt: "2026-08-23",
    blocks: [
      { type: "workbench", variant: editorial.format, eyebrow: workbenchEyebrow, heading: workbenchHeading, intro: workbenchIntro, items: workbenchItems },
      { type: "prose", eyebrow: "Operating principle", heading: principleHeading, paragraphs: principleParagraphs, bullets: principleBullets },
      scenario,
      { type: "faq", heading: "Questions to resolve before shipping", items: faqItems }
    ]
  };
}

